import{_ as o,C as i,o as s,c as d,a2 as t,E as r}from"./chunks/framework.CnJ-JtFX.js";const q=JSON.parse('{"title":"第 15 章 · Capstone 综合实战：从选型到上线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/15-capstone.md","filePath":"guide/15-capstone.md","lastUpdated":1792683644000}'),l={name:"guide/15-capstone.md"};function c(n,a,m,p,h,u){const e=i("ComicFrame");return s(),d("div",null,[a[0]||(a[0]=t('<h1 id="第-15-章-·-capstone-综合实战-从选型到上线" tabindex="-1">第 15 章 · Capstone 综合实战：从选型到上线 <a class="header-anchor" href="#第-15-章-·-capstone-综合实战-从选型到上线" aria-label="Permalink to &quot;第 15 章 · Capstone 综合实战：从选型到上线&quot;">​</a></h1><blockquote class="meta"><p><strong>前置章节</strong>：<a href="./../guide/14-product-comparison">第 14 章 · 产品横向对比</a><br><strong>所需环境</strong>：Node 20 + pnpm 9.15.4 + 现代浏览器（烟测用 headless chromium）；本章 lab 在 <code>labs/capstone</code>，是 amis + Formily 的组合工程。<br><strong>难度</strong>：★★★★<br><strong>本章交付物</strong>：客户运营后台（概览 + CRUD + 复杂表单 + 导出）、E2E 烟测 7 项全绿。</p></blockquote><p>本章是产品实战卷的收尾——综合运用 amis 和 Formily，完成一个完整的&quot;客户运营后台&quot;。需求覆盖了中后台最常见的场景：概览卡片、列表 CRUD、复杂表单（联动 + 异步校验）、状态筛选、数据导出。</p><p>关键决策是<strong>组合使用</strong>：amis 负责它擅长的列表和概览，Formily 负责它擅长的复杂表单，两者在同一个 React 工程里通过路由串联，不需要 iframe。这验证了第 14 章的选型结论——没有银弹，按场景组合。</p><h2 id="本章你将获得" tabindex="-1">本章你将获得 <a class="header-anchor" href="#本章你将获得" aria-label="Permalink to &quot;本章你将获得&quot;">​</a></h2><p>读完本章并跑通 lab，你应该能：</p><ol><li>独立完成一个中后台全栈需求的低代码实现，知道什么场景用 amis、什么场景用 Formily；</li><li>在 amis 里通过自定义 fetcher 对接内存/真实后端，理解 amis 的数据协议；</li><li>在 Formily 里实现字段联动（<code>onFieldReact</code>）和异步校验（Promise validator）；</li><li>处理amis 和 Formily 在同一工程共存时的集成坑（路由跳转、样式隔离、数据边界）；</li><li>写一个端到端烟测，验证从&quot;打开首页 → 新增客户 → 表单校验 → 保存 → 列表出现&quot;的完整链路。</li></ol><h2 id="先看漫画" tabindex="-1">先看漫画 <a class="header-anchor" href="#先看漫画" aria-label="Permalink to &quot;先看漫画&quot;">​</a></h2>',8)),r(e,{ep:"EP.15",slug:"capstone",title:"从选型到上线"}),a[1]||(a[1]=t(`<p>这一话画的是 capstone 的完整决策链——需求评审时标签君面对五个产品做选型，像素酱拆解架构（amis 列表 + Formily 表单 + React Router 串联），编码时验证两者在同一 DOM 共存，最后码叔复盘&quot;组合拳比单打独斗强&quot;。逐格讲解、坑点清单和三道自测题在 <a href="./../comics/EP.15-capstone">EP.15 漫画讲解</a>。</p><h2 id="从一个真实问题说起" tabindex="-1">从一个真实问题说起 <a class="header-anchor" href="#从一个真实问题说起" aria-label="Permalink to &quot;从一个真实问题说起&quot;">​</a></h2><p>假设你是某 SaaS 公司的前端，产品经理丢过来一个需求：做一个&quot;客户运营后台&quot;，让运营同学管理客户信息。具体功能：</p><ol><li><strong>概览页</strong>：三张统计卡片——客户总数、活跃客户数、VIP 客户数；</li><li><strong>客户列表</strong>：表格展示所有客户，支持按姓名/状态/等级筛选，支持编辑和删除；</li><li><strong>新增/编辑客户</strong>：一个复杂表单，字段包括姓名、邮箱、电话、等级、行业、状态、备注；</li><li><strong>表单联动</strong>：客户等级选 SVIP 时，出现&quot;专属客服&quot;字段；</li><li><strong>异步校验</strong>：邮箱不能重复，需要查库校验；</li><li><strong>导出</strong>：把客户列表导出成 CSV。</li></ol><p>你翻了一下第 14 章的选型矩阵，发现：</p><ul><li>概览卡片和列表 CRUD → amis 最擅长（Schema 驱动，开箱即用）；</li><li>复杂表单（联动 + 异步校验）→ Formily 最擅长（领域模型 + reactions）；</li><li>如果全用 amis，表单联动和异步校验会很别扭；</li><li>如果全用 Formily，列表和概览要自己写大量模板代码。</li></ul><p><strong>结论：组合使用</strong>。amis 做列表和概览，Formily 做表单，用 React Router 把三个页面串起来。数据统一存 localStorage（无后端），amis 通过自定义 fetcher 读写，Formily 直接读写同一个 db 模块。这种组合既保留了 amis 在列表场景的高效率，又发挥了 Formily 在复杂表单上的表达力，是中后台需求的典型解法。</p><h2 id="原理拆解" tabindex="-1">原理拆解 <a class="header-anchor" href="#原理拆解" aria-label="Permalink to &quot;原理拆解&quot;">​</a></h2><h3 id="架构拆解" tabindex="-1">架构拆解 <a class="header-anchor" href="#架构拆解" aria-label="Permalink to &quot;架构拆解&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  React Router                    │</span></span>
<span class="line"><span>│  /            /customers        /customers/new   │</span></span>
<span class="line"><span>└──────┬───────────────┬───────────────┬───────────┘</span></span>
<span class="line"><span>       │               │               │</span></span>
<span class="line"><span>   ┌───▼───┐      ┌────▼────┐     ┌────▼─────┐</span></span>
<span class="line"><span>   │ amis  │      │  amis   │     │ Formily  │</span></span>
<span class="line"><span>   │概览卡片│      │CRUD 列表│     │复杂表单   │</span></span>
<span class="line"><span>   └───────┘      └────┬────┘     └────┬─────┘</span></span>
<span class="line"><span>                       │               │</span></span>
<span class="line"><span>                  ┌────▼───────────────▼────┐</span></span>
<span class="line"><span>                  │   shared/db (localStorage) │</span></span>
<span class="line"><span>                  └──────────────────────────┘</span></span></code></pre></div><ul><li><strong>amis 页面</strong>（概览、列表）：用 <code>amis.render(schema, {}, { fetcher })</code> 渲染，fetcher 拦截 <code>/api/*</code> 请求，调用 <code>db</code> 模块返回数据；</li><li><strong>Formily 页面</strong>（新增/编辑）：用 <code>createForm</code> + <code>Field</code> 组件，直接调用 <code>db.create</code> / <code>db.update</code>；</li><li><strong>数据层</strong>：<code>db</code> 模块封装 localStorage CRUD，amis 和 Formily 共用同一个数据源；</li><li><strong>路由</strong>：React Router 三个路由，编辑页通过 <code>:id</code> 参数区分新增/编辑。</li></ul><p>这个架构的核心是&quot;数据层统一、视图层分工&quot;——amis 和 Formily 各自渲染自己擅长的视图，但读写的是同一份数据。</p><h3 id="amis-的数据协议" tabindex="-1">amis 的数据协议 <a class="header-anchor" href="#amis-的数据协议" aria-label="Permalink to &quot;amis 的数据协议&quot;">​</a></h3><p>amis 的所有数据请求都走 <code>env.fetcher</code>。fetcher 收到 <code>{ url, method, query, data }</code>，返回 <code>{ status: 0, data, msg: &quot;&quot; }</code>（status=0 表示成功）。</p><p>关键约定：</p><ul><li><strong>列表接口</strong>：返回 <code>{ items: [], total: n }</code>，crud 组件自动渲染分页；</li><li><strong>表单接口</strong>：返回 <code>{ ...entity }</code>，amis 自动回填表单；</li><li><strong>失败</strong>：返回 <code>{ status: 1, msg: &quot;错误信息&quot; }</code>，amis 会 toast 提示。</li></ul><p>capstone 的 <code>amisFetcher</code> 拦截了 6 个路径：<code>GET /api/stats</code>、<code>GET /api/customers</code>、<code>POST /api/customers</code>、<code>PUT /api/customers/:id</code>、<code>DELETE /api/customers/:id</code>、<code>GET /api/customers/export</code>。</p><h3 id="formily-的联动与校验" tabindex="-1">Formily 的联动与校验 <a class="header-anchor" href="#formily-的联动与校验" aria-label="Permalink to &quot;Formily 的联动与校验&quot;">​</a></h3><p><strong>联动</strong>用 <code>onFieldReact(&quot;level&quot;, field =&gt; {...})</code>：监听 level 字段变化，当值为 &quot;svip&quot; 时显示 vipService 字段，否则隐藏并清空。这是 Formily 的响应式模型——字段变化自动触发副作用，不需要手动写事件监听。</p><p><strong>异步校验</strong>用 <code>validator</code> 返回 Promise：邮箱校验里 <code>setTimeout</code> 模拟查库，<code>db.emailExists</code> 检查是否重复。校验通过 resolve(true)，失败 reject(Error(&quot;消息&quot;))。</p><h3 id="amis-与-formily-的集成点" tabindex="-1">amis 与 Formily 的集成点 <a class="header-anchor" href="#amis-与-formily-的集成点" aria-label="Permalink to &quot;amis 与 Formily 的集成点&quot;">​</a></h3><p>两个产品在同一工程共存，有三个集成点要处理：</p><ol><li><strong>路由跳转</strong>：amis 的 <code>actionType: &quot;url&quot;</code> 会调 <code>window.location.href</code>，在 SPA 里会整页刷新。解决方案是把&quot;新增客户&quot;按钮放在 amis 容器外，用 React Router 的 <code>&lt;Link&gt;</code> 跳转；</li><li><strong>样式隔离</strong>：amis 用 <code>amis/lib/themes/default.css</code>，Formily 用 antd 的 <code>reset.css</code>。两者类名不冲突，但 amis 的全局样式（如 <code>body</code> 字体）可能影响 Formily。capstone 里没有明显冲突，但如果有，可以用 CSS 作用域隔离；</li><li><strong>数据边界</strong>：amis 走 fetcher 读写 db，Formily 直接调用 db。两者共享同一个 localStorage key，数据实时同步——amis 列表新增后刷新能看到 Formily 创建的客户。</li></ol><h3 id="为什么不用-iframe-集成" tabindex="-1">为什么不用 iframe 集成？ <a class="header-anchor" href="#为什么不用-iframe-集成" aria-label="Permalink to &quot;为什么不用 iframe 集成？&quot;">​</a></h3><p>很多低代码平台（如 lowcode-engine、tmagic-editor）用 iframe 隔离设计器和运行时。但 capstone 里 amis 和 Formily 不需要 iframe，原因有三：</p><p><strong>第一，两者都是普通 React 组件</strong>。amis 的 <code>render()</code> 返回 React 元素，Formily 的 <code>&lt;Form&gt;</code> 也是 React 组件，它们可以在同一个 React 树里共存，不需要 iframe 隔离作用域。</p><p><strong>第二，iframe 会增加通信成本</strong>。如果用 iframe 嵌 Formily，amis 和 Formily 之间要通过 <code>postMessage</code> 传递数据（如新客户信息），还要处理 iframe 高度自适应、跨域等问题。同进程直接调用 db 模块简单得多。</p><p><strong>第三，样式和路由可以统一管理</strong>。同一进程下，amis 和 Formily 共享同一个 React Router 和全局样式，导航切换是 SPA 级别的，体验更流畅。</p><p>只有在需要强隔离（如第三方插件不受信任）或技术栈不兼容（如一个用 Vue 一个用 React）时，才需要 iframe。capstone 两个产品都是 React 生态，同进程是最优解。</p><h3 id="数据一致性保证" tabindex="-1">数据一致性保证 <a class="header-anchor" href="#数据一致性保证" aria-label="Permalink to &quot;数据一致性保证&quot;">​</a></h3><p>amis 和 Formily 共用 <code>db</code> 模块，本质上是共用一个 localStorage 单例。一致性保证来自两点：</p><ol><li><strong>所有写操作都走 db 模块</strong>：amis 的 fetcher 调 <code>db.create/update/remove</code>，Formily 的表单提交也调 <code>db.create/update</code>。没有&quot;绕过 db 直接改 localStorage&quot;的路径。</li><li><strong>读操作实时从 localStorage 加载</strong>：<code>db.list()</code> 每次都 <code>localStorage.getItem</code> 再 parse，不是缓存内存。所以 Formily 创建客户后，amis 列表刷新（fetcher 重新调 <code>db.list()</code>）能立即看到新数据。</li></ol><p>这种&quot;单数据源 + 实时读&quot;的模式保证了一致性，但缺点是每次读都要 parse JSON，数据量大时会有性能问题。生产环境可以加内存缓存 + 变更通知机制。</p><h2 id="产品对照" tabindex="-1">产品对照 <a class="header-anchor" href="#产品对照" aria-label="Permalink to &quot;产品对照&quot;">​</a></h2><p>本章是组合使用，对照一下&quot;全用 amis&quot; vs &quot;全用 Formily&quot; vs &quot;amis + Formily&quot;：</p><table tabindex="0"><thead><tr><th>维度</th><th>全用 amis</th><th>全用 Formily</th><th>amis + Formily（capstone）</th></tr></thead><tbody><tr><td>概览卡片</td><td>原生支持（service + tpl）</td><td>要自己写 React</td><td>amis 原生</td></tr><tr><td>列表 CRUD</td><td>原生支持（crud）</td><td>要自己写表格</td><td>amis 原生</td></tr><tr><td>表单联动</td><td>expressions（弱）</td><td>reactions（强）</td><td>Formily 强</td></tr><tr><td>异步校验</td><td>支持但写法绕</td><td>Promise validator（原生）</td><td>Formily 原生</td></tr><tr><td>开发效率</td><td>列表快、表单慢</td><td>表单快、列表慢</td><td>都快</td></tr><tr><td>维护成本</td><td>表单联动难维护</td><td>列表代码多</td><td>各取所长</td></tr></tbody></table><p>组合方案的核心价值：<strong>让每个产品做它最擅长的事</strong>。amis 的列表和概览用 Schema 几分钟就能搭好，Formily 的复杂表单用领域模型优雅地处理联动和校验。</p><h2 id="动手实现" tabindex="-1">动手实现 <a class="header-anchor" href="#动手实现" aria-label="Permalink to &quot;动手实现&quot;">​</a></h2><h3 id="_1-启动-capstone" tabindex="-1">1. 启动 capstone <a class="header-anchor" href="#_1-启动-capstone" aria-label="Permalink to &quot;1. 启动 capstone&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labs/capstone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # http://localhost:5179</span></span></code></pre></div><p>打开后左侧导航有三个入口：概览、客户列表、新增客户。</p><h3 id="_2-验证概览页" tabindex="-1">2. 验证概览页 <a class="header-anchor" href="#_2-验证概览页" aria-label="Permalink to &quot;2. 验证概览页&quot;">​</a></h3><p>访问 <code>/</code>，应该看到三张卡片：客户总数、活跃客户、VIP 客户。数字来自 <code>GET /api/stats</code>，由 <code>amisFetcher</code> 从 localStorage 计算返回。</p><h3 id="_3-验证列表-crud" tabindex="-1">3. 验证列表 CRUD <a class="header-anchor" href="#_3-验证列表-crud" aria-label="Permalink to &quot;3. 验证列表 CRUD&quot;">​</a></h3><p>访问 <code>/customers</code>，看到客户表格（种子数据 3 条）。可以：</p><ul><li>用筛选器按姓名/状态/等级过滤；</li><li>点&quot;编辑&quot;跳转到 Formily 表单（回填数据）；</li><li>点&quot;删除&quot;移除客户（带确认）；</li><li>点&quot;导出 CSV&quot;下载 customers.csv。</li></ul><h3 id="_4-验证复杂表单" tabindex="-1">4. 验证复杂表单 <a class="header-anchor" href="#_4-验证复杂表单" aria-label="Permalink to &quot;4. 验证复杂表单&quot;">​</a></h3><p>访问 <code>/customers/new</code>，填写表单：</p><ul><li>姓名、邮箱、电话（必填 + 格式校验）；</li><li>等级选 SVIP → 出现&quot;专属客服&quot;字段（联动）；</li><li>邮箱填已存在的邮箱 → 异步校验报错&quot;该邮箱已存在&quot;；</li><li>选行业、状态，点保存 → 回到列表，新客户出现。</li></ul><h3 id="_5-跑-e2e-烟测" tabindex="-1">5. 跑 E2E 烟测 <a class="header-anchor" href="#_5-跑-e2e-烟测" aria-label="Permalink to &quot;5. 跑 E2E 烟测&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 启动 preview 5279</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 7 项断言</span></span></code></pre></div><p>烟测覆盖：概览渲染 → 列表种子数据 → 跳转表单 → 表单输入框渲染 → SVIP 联动 → 保存后列表出现新客户。</p><h3 id="_6-扩展练习" tabindex="-1">6. 扩展练习 <a class="header-anchor" href="#_6-扩展练习" aria-label="Permalink to &quot;6. 扩展练习&quot;">​</a></h3><p>跑通基础功能后，可以尝试以下扩展，加深对组合使用的理解：</p><ul><li><strong>批量操作</strong>：给 amis 列表加多选 + 批量修改状态（<code>selectable: true</code> + <code>bulkActions</code>）；</li><li><strong>分页</strong>：当前 fetcher 返回全部数据，改成支持 <code>page</code>/<code>perPage</code> 分页，amis crud 会自动渲染分页器；</li><li><strong>表单分步</strong>：把 Formily 表单拆成两步（基本信息 + 等级信息），用 Formily 的 <code>FormStep</code> 或自定义步骤条；</li><li><strong>真实后端</strong>：把 <code>db</code> 模块换成真实 REST API，amis fetcher 用 <code>fetch</code> 转发，Formily 也调同一 API——数据层替换不影响 UI 层。</li></ul><h2 id="跑不起来" tabindex="-1">跑不起来？ <a class="header-anchor" href="#跑不起来" aria-label="Permalink to &quot;跑不起来？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>可能原因</th><th>排查步骤</th></tr></thead><tbody><tr><td>概览卡片数字显示 <code>\${total}</code></td><td>amis 模板语法错</td><td>amis 的 tpl 用 <code>\${var}</code> 不是 <code>&amp;#123;&amp;#123;var&amp;#125;&amp;#125;</code>；检查 schema 里的模板字符串</td></tr><tr><td>列表报 <code>data.items 必须是数组</code></td><td>fetcher 返回格式不对</td><td>确认 fetcher 返回 <code>{ status: 0, data: { items: [], total } }</code>；url 要先 <code>split(&quot;?&quot;)[0]</code> 去掉 query</td></tr><tr><td>点&quot;新增客户&quot;没跳转</td><td>amis 的 url action 不触发 SPA 路由</td><td>用 React Router <code>&lt;Link&gt;</code> 放在 amis 外，不要用 amis 的 <code>actionType: &quot;url&quot;</code></td></tr><tr><td>Formily 表单字段不显示</td><td>用了 FormProvider 而不是 Form</td><td><code>@formily/antd-v5</code> 的 <code>Form</code> 组件内部已含 Provider；直接用 <code>&lt;Form form={form}&gt;</code></td></tr><tr><td>保存按钮点不动</td><td>按钮文字有字间距</td><td>antd 按钮文字被样式加了 <code>letter-spacing</code>，选择器用 <code>filter({ hasText: &quot;保&quot; })</code> 而不是精确匹配</td></tr><tr><td>邮箱异步校验永远失败</td><td>db.emailExists 逻辑错</td><td>检查 excludeId 参数；编辑模式要排除当前客户的 id</td></tr></tbody></table><h2 id="避坑清单" tabindex="-1">避坑清单 <a class="header-anchor" href="#避坑清单" aria-label="Permalink to &quot;避坑清单&quot;">​</a></h2><ol><li><strong>amis 的 fetcher 返回格式必须是 <code>{ status, msg, data }</code></strong>：status=0 成功，非 0 失败。不要返回 axios 风格的 <code>{ status: 200, data }</code>，amis 会把外层 status 当业务状态码。</li><li><strong>amis 的 url 匹配要去掉 query 字符串</strong>：<code>api.url</code> 可能带 <code>?page=1&amp;perPage=10</code>，必须 <code>url.split(&quot;?&quot;)[0]</code> 再匹配，否则 GET 列表会匹配失败。</li><li><strong>不要用 amis 的 <code>actionType: &quot;url&quot;</code> 在 SPA 里跳转</strong>：它会调 <code>window.location.href</code> 导致整页刷新。用 React Router 的 <code>&lt;Link&gt;</code> 或 <code>useNavigate</code>。</li><li><strong>Formily 用 <code>Form</code> 不用 <code>FormProvider</code></strong>：<code>@formily/antd-v5</code> 的 <code>Form</code> 组件已经封装了 FormProvider，再套一层 FormProvider 会导致 context 丢失、字段不渲染。</li><li><strong>Formily 的 Submit 按钮文字有字间距</strong>：antd 的按钮样式加了 <code>letter-spacing</code>，导致 &quot;保存&quot; 变成 &quot;保 存&quot;，自动化测试要用模糊匹配。</li><li><strong>amis 和 Formily 共享数据源要走同一 db 模块</strong>：不要各自维护一份数据，否则列表和表单的数据会不一致。capstone 用 localStorage 单例，两边都调同一个 db。</li><li><strong>导出 CSV 要返回 dataURL</strong>：amis 的 <code>actionType: &quot;download&quot;</code> 期望接口返回 <code>{ url: &quot;data:...&quot;, filename: &quot;x.csv&quot; }</code>，不要返回文件流——amis 的 download action 会直接用 url 触发下载。</li></ol><h2 id="小结与自测" tabindex="-1">小结与自测 <a class="header-anchor" href="#小结与自测" aria-label="Permalink to &quot;小结与自测&quot;">​</a></h2><h3 id="你应该记住的" tabindex="-1">你应该记住的 <a class="header-anchor" href="#你应该记住的" aria-label="Permalink to &quot;你应该记住的&quot;">​</a></h3><ul><li>组合使用比单一产品更强：amis 做列表/概览，Formily 做复杂表单</li><li>amis 的数据协议：fetcher 返回 <code>{ status: 0, data, msg }</code>，列表要 <code>{ items, total }</code></li><li>Formily 的联动用 <code>onFieldReact</code>，异步校验用 Promise validator</li><li>SPA 里不要用 amis 的 <code>actionType: &quot;url&quot;</code>，用 React Router Link</li><li>Formily 用 <code>Form</code> 组件（已含 Provider），不要套 FormProvider</li><li>数据层统一：amis 和 Formily 共用同一个 db 模块</li><li>导出用 dataURL：amis download action 期望 <code>{ url, filename }</code> 格式</li></ul><h3 id="自测题" tabindex="-1">自测题 <a class="header-anchor" href="#自测题" aria-label="Permalink to &quot;自测题&quot;">​</a></h3><ol><li><strong>选择题</strong>：capstone 里为什么不用 amis 做复杂表单？（A）amis 不支持表单；（B）amis 的表达式联动和异步校验写法别扭，Formily 的领域模型更适合；（C）amis 的表单样式不好看；（D）amis 不能做必填校验。</li><li><strong>选择题</strong>：amis 的 fetcher 返回列表数据时，正确的格式是？（A）<code>[{ id:1, name:&quot;x&quot; }]</code>；（B）<code>{ status: 0, data: [{ id:1 }] }</code>；（C）<code>{ status: 0, data: { items: [{ id:1 }], total: 1 } }</code>；（D）<code>{ items: [{ id:1 }] }</code>。</li><li><strong>思考题</strong>：如果 capstone 的客户列表要支持&quot;批量选中后批量修改状态&quot;，应该用 amis 还是自己写 React 组件？为什么？</li></ol><h3 id="自测题参考答案" tabindex="-1">自测题参考答案 <a class="header-anchor" href="#自测题参考答案" aria-label="Permalink to &quot;自测题参考答案&quot;">​</a></h3><ol><li>答案 B。amis 支持表单且有校验，但它的联动靠 expressions（字符串表达式），异步校验要写 fetcher 适配器，复杂场景下可读性和可维护性差。Formily 的领域模型（Field + reactions + Promise validator）是为复杂表单设计的，联动和校验都是一等公民。</li><li>答案 C。amis 的 crud 组件期望 <code>data.items</code> 是数组、<code>data.total</code> 是总数，外层 <code>status: 0</code> 表示成功。A 是裸数组（amis 会报错），B 缺少 items/total 结构，D 缺少 status 包裹。</li><li>应该用 amis。amis 的 crud 组件原生支持多选（<code>selectable: true</code>）和批量操作（<code>bulkActions</code>），只需在 schema 里配置批量 action 调用后端接口。自己写 React 组件要处理选中状态、全选逻辑、批量请求等，重复造轮子。amis 在列表操作场景下的生产力远高于手写。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>产品实战卷到此结束。你已经掌握了五个主线低代码产品的核心用法，以及如何按场景组合使用。接下来进入<strong>进阶卷（第 16-20 章）</strong>——不依赖任何商业低代码框架，从零搭建一个教学级低代码系统，覆盖 Schema 定义、递归渲染、拖拽设计器、撤销重做、插件系统、出码产物。进阶卷会揭示低代码引擎的底层原理。</p>`,68))])}const b=o(l,[["render",c]]);export{q as __pageData,b as default};
